package mz.bam.seeky.android;
import android.app.*;import android.content.*;import android.database.*;import android.database.sqlite.*;import android.net.Uri;import android.os.*;import android.provider.*;import java.io.*;import java.nio.file.Files;import java.util.*;import java.util.zip.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(org.robolectric.RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=33,application=Application.class) @LooperMode(LooperMode.Mode.PAUSED)
public class Bible5180Test {
 WorkTestSupport w;static Map<String,File> treeFiles=new LinkedHashMap<>();static Runnable pause;
 @Before public void before()throws Exception{w=new WorkTestSupport();treeFiles.clear();pause=null;}
 @After public void close(){w.close();}
 interface Checked{void run()throws Exception;}
 void rejected(Checked call,String fragment)throws Exception{try{call.run();fail("Expected rejection");}catch(IOException e){assertTrue(e.toString(),e.toString().contains(fragment));}}
 static String usx(String book,String text){return "<usx version='3.0'><book code='"+book+"' style='id'/><chapter number='1' style='c' sid='"+book+" 1'/><para style='p'><verse number='1' style='v' sid='"+book+" 1:1'/>"+text+"<verse eid='"+book+" 1:1'/></para><chapter eid='"+book+" 1'/></usx>";}
 List<String> read(String xml)throws Exception{List<String> result=new ArrayList<>();BibleUsx.read(new ByteArrayInputStream(xml.getBytes("UTF-8")),(b,c,v,t)->result.add(b+" "+c+":"+v+" "+t),()->false,()->{});return result;}
 File module(boolean names)throws Exception{File f=new File(w.app.getCacheDir(),UUID.randomUUID()+".SQLite3");try(SQLiteDatabase db=SQLiteDatabase.openOrCreateDatabase(f,null)){db.execSQL("CREATE TABLE verses(book_number INTEGER,chapter INTEGER,verse INTEGER,text TEXT)");if(names){db.execSQL("CREATE TABLE books(book_number INTEGER,long_name TEXT,short_name TEXT)");db.execSQL("INSERT INTO books VALUES(9,'Isaías','Is')");}db.execSQL("INSERT INTO verses VALUES(?,5,6,?)",new Object[]{names?9:290,"Palavra<S>123</S> &amp; <i>vida</i><n>Nota oculta</n><br/>Texto &#225;."});db.execSQL("INSERT INTO verses VALUES(470,1,1,'Texto de ensaio Mateus.')");}return f;}
 String job(String name,File f)throws Exception{return w.job("bible",new JSONObject().put("name",name).put("mime","application/octet-stream").put("title","Tradução de ensaio").put("uri",w.source(UUID.randomUUID().toString(),name,f).toString()));}
 String job(String name,String text)throws Exception{return w.job("bible",new JSONObject().put("name",name).put("mime","application/octet-stream").put("title","Tradução de ensaio").put("uri",w.source(UUID.randomUUID().toString(),name,text).toString()));}
 long published(){try(PlusStore db=new PlusStore(w.app)){return DatabaseUtils.longForQuery(db.getReadableDatabase(),"SELECT COUNT(*) FROM bible_verses",null);}}
 String verse(String book,int chapter,int verse){try(PlusStore db=new PlusStore(w.app)){return db.rows("bible_verses","book=? AND chapter=? AND verse=?",new String[]{book,""+chapter,""+verse},null,1).get(0).s("value");}}
 File zip(String... pairs)throws Exception{File file=new File(w.app.getCacheDir(),UUID.randomUUID()+".zip");try(ZipOutputStream z=new ZipOutputStream(new FileOutputStream(file))){for(int i=0;i<pairs.length;i+=2)ChapterExportTest.entry(z,pairs[i],pairs[i+1]);}return file;}
 void seed(String id,int next,String book,String text)throws Exception{try(SQLiteDatabase db=SQLiteDatabase.openOrCreateDatabase(new File(SummaryWork.root(w.app,id),"bible.db"),null)){db.execSQL("CREATE TABLE verses(book TEXT,chapter INTEGER,verse INTEGER,value TEXT,PRIMARY KEY(book,chapter,verse))");db.execSQL("CREATE TABLE checkpoint(id INTEGER PRIMARY KEY,position INTEGER,value TEXT)");db.execSQL("INSERT INTO verses VALUES(?,1,1,?)",new Object[]{book,text});db.execSQL("INSERT INTO checkpoint VALUES(1,?,'{}')",new Object[]{next});}}
 @Test public void readsUsxThreeMilestonesAndCanonicalBook()throws Exception{assertEquals(Arrays.asList("Génesis 1:1 Texto de ensaio."),read(usx("GEN","Texto de ensaio.")));}
 @Test public void readsUsxTwoAndParagraphContinuation()throws Exception{String xml="<usx version='2.0'><book code='JHN'/><chapter number='3'/><para style='p'><verse number='16'/>Primeiro <char style='it'>texto</char>.</para><para style='p'>Outra linha.<verse number='17'/>Texto seguinte.</para></usx>";assertEquals(Arrays.asList("João 3:16 Primeiro texto. Outra linha.","João 3:17 Texto seguinte."),read(xml));}
 @Test public void notesHeadingsAndVerseLabelsStayOutOfScripture()throws Exception{String xml="<usx><book code='PSA'/><chapter number='1'/><para style='s1'>Título</para><para style='p'><verse number='1'/>Pa<char style='it'>la</char>vra<note style='f'>NOTA</note><char style='vp'>1</char> final.</para><para style='s2'>Outro título</para><para style='p'><verse number='2'/>Segundo.</para></usx>";assertEquals(Arrays.asList("Salmos 1:1 Palavra final.","Salmos 1:2 Segundo."),read(xml));}
 @Test public void bridgedVersesResolveAtEachReference()throws Exception{assertEquals(Arrays.asList("Génesis 1:3 Texto unido.","Génesis 1:4 Texto unido."),read(usx("GEN","Texto unido.").replace("number='1' style='v'","number='3-4' style='v'")));}
 @Test public void suffixedVersesAreCombinedWithoutDuplicates()throws Exception{String xml="<usx><book code='ROM'/><chapter number='1'/><para><verse number='3a'/>Parte A.<verse eid='ROM 1:3a'/><verse number='3b'/>Parte B.<verse number='4'/>Próximo.</para></usx>";assertEquals(Arrays.asList("Romanos 1:3 Parte A. Parte B.","Romanos 1:4 Próximo."),read(xml));}
 @Test public void entitiesAndUnicodeSurvive()throws Exception{assertTrue(read(usx("ISA","Ação &amp; &#225;gua.")).get(0).endsWith("Ação & água."));}
 @Test public void dtdAndExternalEntitiesAreRejected()throws Exception{rejected(()->read("<!DOCTYPE usx [<!ENTITY x SYSTEM 'file:///etc/passwd'>]>"+usx("GEN","&x;")),"USX inválido");}
 @Test public void missingBookOrChapterIsRejected()throws Exception{rejected(()->read("<usx><verse number='1'/>Texto.</usx>"),"sem livro ou capítulo");}
 @Test public void malformedXmlFails()throws Exception{rejected(()->read(usx("GEN","Teste").replace("</para>","</wrong>")),"USX inválido");}
 @Test public void cancellationStopsParsing()throws Exception{try{BibleUsx.read(new ByteArrayInputStream(usx("GEN","Texto").getBytes("UTF-8")),(b,c,v,t)->{},()->true,()->{});fail();}catch(InterruptedIOException expected){}}
 @Test public void auxiliaryXmlProbeIsFalseAndUsxIsTrue()throws Exception{assertFalse(BibleUsx.isUsx(new ByteArrayInputStream("<styles/>".getBytes("UTF-8"))));assertTrue(BibleUsx.isUsx(new ByteArrayInputStream(usx("GEN","Texto").getBytes("UTF-8"))));}
 @Test public void standardMyBibleNumberingIncludesIsaiahAndMatthewAndPreservesSource()throws Exception{File f=module(false);String hash=StudyFiles.hash(f);w.run(job("ARAi+.SQLite3",f));assertEquals(2,published());assertEquals("Palavra & vida Texto á.",verse("Isaías",5,6));assertEquals("Texto de ensaio Mateus.",verse("Mateus",1,1));assertEquals(hash,StudyFiles.hash(f));}
 @Test public void metadataNamesSupportCustomBookNumbers()throws Exception{w.run(job("Biblia.SQLite3",module(true)));assertEquals("Palavra & vida Texto á.",verse("Isaías",5,6));}
 @Test public void binLabelIsDetectedBySqliteHeader()throws Exception{w.run(job("Biblia.bin",module(false)));assertEquals(2,published());}
 @Test public void searchIndexExplainsWhichFileToChoose()throws Exception{String id=job("ARAi+.SQLite3.search","index");rejected(()->w.run(id),"sem .search");assertEquals(0,published());}
 @Test public void commentaryDatabaseIsNotPublishedAsBible()throws Exception{File f=new File(w.app.getCacheDir(),"commentary.SQLite3");try(SQLiteDatabase db=SQLiteDatabase.openOrCreateDatabase(f,null)){db.execSQL("CREATE TABLE commentaries(text TEXT)");}String id=job("teste.commentaries.SQLite3",f);rejected(()->w.run(id),"não contém a tabela");assertEquals(0,published());}
 @Test public void compressedMyBibleTextFailsInsteadOfImportingGibberish()throws Exception{File f=module(false);try(SQLiteDatabase db=SQLiteDatabase.openDatabase(f.getPath(),null,0)){db.execSQL("UPDATE verses SET text=x'1234'");}String id=job("teste.SQLite3",f);rejected(()->w.run(id),"comprimidos");assertEquals(0,published());}
 @Test public void unknownBookFailsWithoutPublishingAPartialTranslation()throws Exception{File f=module(false);try(SQLiteDatabase db=SQLiteDatabase.openDatabase(f.getPath(),null,0)){db.execSQL("INSERT INTO verses VALUES(9999,1,1,'Texto')");}String id=job("teste.SQLite3",f);rejected(()->w.run(id),"desconhecido");assertEquals(0,published());}
 @Test public void chapterZeroAndVerseZeroHeadingsAreIgnored()throws Exception{File f=module(false);try(SQLiteDatabase db=SQLiteDatabase.openDatabase(f.getPath(),null,0)){db.execSQL("INSERT INTO verses VALUES(290,0,0,'Título')");}w.run(job("teste.SQLite3",f));assertEquals(2,published());}
 @Test public void zipCombinesBooksAndIgnoresStylesAndCoversAndFrontMatter()throws Exception{File f=zip("release/styles.xml","<styles/>","release/cover.jpg","cover","release/USX_1/00FRT.usx","<usx><book code='FRT'/><para>Prefácio.</para></usx>","release/USX_1/01GEN.usx",usx("GEN","Texto Génesis."),"release/USX_1/02EXO.usx",usx("EXO","Texto Êxodo."));w.run(job("versao.zip",f));assertEquals(2,published());assertEquals("Texto Êxodo.",verse("Êxodo",1,1));}
 @Test public void committedZipBookWinsOverStaleTaskJournal()throws Exception{String id=job("versao.zip",zip("01GEN.usx",usx("GEN","Não reler."),"02EXO.usx",usx("EXO","Novo livro.")));seed(id,1,"Génesis","Já guardado.");w.run(id);assertEquals(2,published());assertEquals("Já guardado.",verse("Génesis",1,1));}
 @Test public void committedSingleModuleIsNotReplayedAfterInterruption()throws Exception{String id=job("teste.SQLite3",module(false));seed(id,1,"Génesis","Já guardado.");w.run(id);assertEquals(1,published());assertEquals("Já guardado.",verse("Génesis",1,1));}
 @Test public void mixingVersionsRejectsDuplicatesAndPreservesExistingBible()throws Exception{w.run(job("original.usx",usx("ISA","Texto anterior.")));String id=job("mistura.zip",zip("v1/GEN.usx",usx("GEN","Um."),"v2/GEN.usx",usx("GEN","Dois.")));rejected(()->w.run(id),"repetido");assertEquals(1,published());assertEquals("Texto anterior.",verse("Isaías",1,1));}
 @Test public void invalidUsxDoesNotPublishAndRetryKeepsCommittedBooks()throws Exception{String id=job("versao.zip",zip("01GEN.usx",usx("GEN","Guardado."),"02EXO.usx","<usx>"));rejected(()->w.run(id),"USX inválido");assertEquals(0,published());try(SQLiteDatabase db=SQLiteDatabase.openDatabase(new File(SummaryWork.root(w.app,id),"bible.db").getPath(),null,0)){assertEquals(1,DatabaseUtils.longForQuery(db,"SELECT position FROM checkpoint",null));assertEquals(1,DatabaseUtils.longForQuery(db,"SELECT COUNT(*) FROM verses",null));}rejected(()->w.run(id),"USX inválido");assertEquals(0,published());}
 @Test public void unsupportedAuxiliaryFileGivesUsefulMessage()throws Exception{String id=job("por_pt-BR.ldml","settings");rejected(()->w.run(id),"configuração ou capa");}
 @Test public void completeLargeModulePublishesThirtyThreeThousandVerses()throws Exception{File f=new File(w.app.getCacheDir(),"large.SQLite3");try(SQLiteDatabase db=SQLiteDatabase.openOrCreateDatabase(f,null)){db.execSQL("CREATE TABLE verses(book_number INTEGER,chapter INTEGER,verse INTEGER,text TEXT)");db.beginTransaction();try(SQLiteStatement insert=db.compileStatement("INSERT INTO verses VALUES(?,?,?,?)")){for(int b=1;b<=66;b++)for(int c=1;c<=10;c++)for(int v=1;v<=50;v++){insert.bindLong(1,b*10);insert.bindLong(2,c);insert.bindLong(3,v);insert.bindString(4,"Versículo de ensaio "+b+" "+c+":"+v);insert.executeInsert();}db.setTransactionSuccessful();}finally{db.endTransaction();}}w.run(job("large.SQLite3",f));assertEquals(33000,published());assertEquals("Versículo de ensaio 29 10:50",verse("Isaías",10,50));}
 public static class Tree extends DocumentsProvider{
  public boolean onCreate(){return true;}public Cursor queryRoots(String[] p){return new MatrixCursor(new String[]{"root_id","document_id"});}public boolean isChildDocument(String p,String c){return c.startsWith(p+"/");}
  MatrixCursor row(String[] projection,List<String> ids){String[] columns=projection==null?new String[]{"document_id","_display_name","mime_type"}:projection;MatrixCursor result=new MatrixCursor(columns);for(String id:ids){Object[] vals=new Object[columns.length];for(int i=0;i<columns.length;i++)vals[i]=columns[i].equals("document_id")?id:columns[i].equals("_display_name")?id.substring(id.lastIndexOf('/')+1):columns[i].equals("mime_type")?treeFiles.containsKey(id)?"application/octet-stream":DocumentsContract.Document.MIME_TYPE_DIR:null;result.addRow(vals);}return result;}
  public Cursor queryDocument(String id,String[] p){return row(p,Arrays.asList(id));}public Cursor queryChildDocuments(String id,String[] p,String o){if(id.equals("root/USX_1")&&pause!=null){Runnable r=pause;pause=null;r.run();}List<String> children=new ArrayList<>();if(id.equals("root"))children.add("root/USX_1");for(String k:treeFiles.keySet())if(k.substring(0,k.lastIndexOf('/')).equals(id))children.add(k);return row(p,children);}
  public ParcelFileDescriptor openDocument(String id,String mode,CancellationSignal s)throws FileNotFoundException{return ParcelFileDescriptor.open(treeFiles.get(id),ParcelFileDescriptor.MODE_READ_ONLY);}
 }
 String treeJob()throws Exception{for(String[] pair:new String[][]{{"root/USX_1/GEN.usx",usx("GEN","Texto Génesis.")},{"root/USX_1/EXO.usx",usx("EXO","Texto Êxodo.")},{"root/styles.xml","<styles/>"},{"root/por_pt-BR.ldml","locale"},{"root/versification.vrs","settings"},{"root/capa.jpg","cover"}}){File f=new File(w.app.getCacheDir(),UUID.randomUUID()+".fixture");Files.write(f.toPath(),pair[1].getBytes("UTF-8"));treeFiles.put(pair[0],f);}ChapterExportTest.register(w.app,"seeky.usx.tree",new Tree(),true);Uri tree=DocumentsContract.buildTreeDocumentUri("seeky.usx.tree","root");String id=w.job("bible",new JSONObject().put("name","Pasta USX").put("mime","inode/directory").put("title","USX Ensaio").put("tree",tree.toString()));try(TaskStore tasks=new TaskStore(w.app)){tasks.getWritableDatabase().insertOrThrow("scan_nodes",null,StudyStore.values("job",id,"uri",DocumentsContract.buildDocumentUriUsingTree(tree,"root").toString()));}return id;}
 @Test public void versionFolderImportsRecursiveUsxAndIgnoresAuxiliaryFiles()throws Exception{String id=treeJob();w.run(id);assertEquals(2,published());assertEquals(3,w.items(id,null));assertEquals("Texto Êxodo.",verse("Êxodo",1,1));}
 @Test public void interruptedFolderDiscoveryResumesWithoutDuplicateItems()throws Exception{String id=treeJob();TaskService.Control control=w.control(id);pause=()->control.stopped=true;try(TaskStore tasks=new TaskStore(w.app)){try{TaskWork.run(w.service,tasks.job(id),tasks,control);fail();}catch(InterruptedIOException expected){}}assertEquals(0,published());w.run(id);assertEquals(2,published());assertEquals(3,w.items(id,null));}
}
